INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (967, 'Axel Adler Scholarship for Sustainability (University of Gothenburg)', 'University of Gothenburg', 'Sweden', 'Full Tuition Waiver', 0, 'Applied for together with the Axel Adler Scholarship in one application. For the 2027 round: apply for a sustainability-focused master''s programme at the University of Gothenburg as your FIRST choice by 15 January 2027, pay the application fee and submit entry-requirement documents by 1 February 2027; eligible applicants receive the scholarship invitation by email around 10 February 2027, and results are emailed on 12 April 2027 (master''s).', '2027-01-15', 'fixed', NULL, NULL, $j$["Master's"]$j$, $j$["Sustainability-focused master's programmes at the University of Gothenburg (the programmes tagged 'Sustainability focused' in the university programme search), applied to as first choice. NOT eligible: bachelor's programmes and the distance-learning master's programme Education for Sustainable Development"]$j$, $j$["Students required to pay tuition fees in Sweden (non-EU/EEA/Swiss citizens without an exempting residence permit)"]$j$, NULL, NULL, false, true, $desc$The Axel Adler Scholarship for Sustainability is an additional, separately counted award inside the University of Gothenburg's Axel Adler Scholarship application: a tuition fee waiver reserved for students admitted to one of the university's sustainability-focused master's programmes. Candidates must meet both the general Axel Adler Scholarship 2027 requirements and the special sustainability requirements, and anyone eligible for both scholarships applies for them in the same single application. Only between 2 and 12 students will be awarded the Axel Adler Scholarship for Sustainability in a round, which makes it far more selective than the main scheme (one scholarship per programme, record 739). The route in is the standard Swedish first admission round: choose a sustainability-focused master's programme as your first choice at universityadmissions.se by 15 January 2027, pay the application fee and submit the entry-requirement documents by 1 February 2027, and the scholarship invitation arrives by email around 10 February 2027 with results for master's applicants on 12 April 2027. Like the main scheme, the award is a waiver paid by the foundations directly to the university (funded by the Adlerbertska foundations together with the Swedish Council for Higher Education, UHR): it covers the tuition fee of the admitted programme but never living expenses or travel, it cannot be combined with another tuition-fee scholarship, and keeping it requires completing at least 75% of each semester's credits. Bachelor's programmes and the distance-learning master's Education for Sustainable Development are explicitly not eligible.$desc$, $req$You must be required to pay tuition fees in Sweden and meet the general Axel Adler Scholarship 2027 requirements - a campus-based University of Gothenburg programme chosen as your first choice, the study application submitted by 15 January 2027 and the application fee plus entry-requirement documents in by 1 February 2027 at universityadmissions.se - and additionally the special requirements for the sustainability variant, i.e. admission to one of the university's sustainability-focused master's programmes (bachelor's programmes and the distance-learning Education for Sustainable Development master's do not count). Eligible applicants apply for the sustainability award inside the same Axel Adler application (invitation emailed around 10 February 2027), where selection rests on the CV and letter of motivation written in the scholarship system (maximum 3,000 characters each; academic staff rank the applications and academic merits may also be considered). Only 2 to 12 awards are made. The waiver cannot be combined with another tuition scholarship (you may apply for several but can be awarded only one), late applications are not considered, fee-status changes must be reported to scholarships@gu.se, and retention requires at least 75% of the semester's credits each semester. No numeric GPA cutoff or scholarship-level IELTS figure is published, so min_gpa/min_ielts are not recorded.$req$, 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship', 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship', 'https://www.universityadmissions.se', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 18) from the 'Axel Adler Scholarship for Sustainability' section and FAQ of the University of Gothenburg's official Axel Adler Scholarship page fetched the same day (additional tuition fee waiver for students admitted to a sustainability-focused master's programme; must meet the general Axel Adler 2027 requirements plus the special sustainability requirements, with a dedicated 2027 requirements PDF; both scholarships applied for in the same application; between 2 and 12 awardees; bachelor's programmes and the distance-learning master's Education for Sustainable Development excluded; round calendar - first-choice application by 15 January 2027, fee and documents by 1 February 2027, invitation email around 10 February 2027, results 12 April 2027 for master's applicants; selection by academic staff on the in-system CV and letter of motivation of max 3,000 characters each; waiver paid by the foundations directly to the university; no living/travel support; cannot be combined with another tuition scholarship; at least 75% of each semester's credits required to keep it; no late applications; funded by the Adlerbertska Scholarship Foundation, the Adlerbertska Grant Foundation and the Swedish Council for Higher Education UHR). The variant was spotted in cleanup pass 111 while retiring duplicate record 423 and is catalogued here as the separate named award it is, distinct from the main Axel Adler Scholarship (record 739). Award stored as NULL (SEK, 'year', 'variable'): a full tuition waiver whose krona value follows the programme fee. deadline_date 2027-01-15 ('fixed') is the binding first-choice study-application deadline of the 2027 round read on the fetched page; status 'upcoming' as the round is yet to reach its January deadline. min_gpa/min_ielts NULL. university_id set to the existing University of Gothenburg record (136), a university_scholarships row added, and the record linked to the existing verified source 2533 (the Axel Adler Scholarship page, repointed in pass 111).$note$, 136, NULL, 'SEK', 'year', 'variable', NULL, 'Full tuition fee waiver for a sustainability-focused master''s programme (awarded to 2-12 students, inside the Axel Adler application); paid directly to the university, no living-cost support', 'The scholarship covers the tuition fee for the admitted sustainability-focused master''s programme in full (paid by the foundations straight to the University of Gothenburg); the fee amount itself varies by programme.', 'No scholarship-level IELTS figure; English requirements are set by each master''s programme''s admission rules.', $j$["First-choice application to a sustainability-focused master's programme at the University of Gothenburg by 15 January 2027, with the application fee paid and entry-requirement documents submitted by 1 February 2027 (universityadmissions.se)", "Scholarship application after the emailed invitation (around 10 February 2027): CV and letter of motivation written in the scholarship application system, max 3,000 characters each"]$j$, NULL, NULL, $json$[{"round": "2027", "study_application_by": "2027-01-15", "documents_by": "2027-02-01", "invitation": "2027-02-10", "results": "2027-04-12", "status": "upcoming"}, {"pattern": "Annual within the Axel Adler Scholarship round: first-choice sustainability-focused master's application by mid-January, documents by 1 February, invitation in February, results in April; 2-12 awards"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (968, 'KTH One-Year Scholarship', 'KTH Royal Institute of Technology', 'Sweden', 'Full Tuition Waiver', 0, 'For CURRENT first-year students of a two-year KTH master''s programme only (you cannot apply before starting at KTH): the scholarship application opens each year on 1 April and closes 15 April, with selection based on the grades from the courses completed in the first year at KTH - the award then waives the tuition fee for the second year. No single next-round date is published, so no deadline_date is recorded.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["Two-year master's programmes at KTH Royal Institute of Technology (NOT joint master programmes or EIT programmes); for students already in their first year at KTH"]$j$, $j$["Current fee-paying KTH master's students (students liable for tuition fees in Sweden - non-EU/EEA/Swiss citizens without an exempting residence permit)"]$j$, NULL, NULL, false, true, $desc$The KTH One-Year Scholarship is KTH's in-course reward: it covers the tuition fee for the second year of a two-year master's programme at KTH and is awarded to current KTH master's students who achieve outstanding results in their first year of studies. It does not include living costs. The selection is based on the applicant's grades from courses completed in the first year of studies at KTH, and the award is competitive - in 2025, 5% of the eligible scholarship applicants were nominated (12 of 220). Eligibility requires being a fee-paying student with satisfactory grades to progress to the second year; KTH One-Year Scholarships are not available for joint master programmes or EIT programmes. The practical consequence for a prospective student is that this is a second chance rather than an entry award: if you start a two-year KTH master's without the (first-priority, pre-entry) KTH Scholarship, strong first-year performance across your courses can still earn you a fully waived second-year tuition fee. Applications run in a short annual window each spring (1-15 April, while you are in the first year).$desc$, $req$Open only to students already studying at KTH: you must be a fee-paying student on a two-year KTH master's programme, have satisfactory grades to progress to the second year, and stand out academically - selection is based on the grades from the courses completed in the first year at KTH. Joint master programmes and EIT programmes are excluded (joint-programme students have the separate KTH Joint Programme Scholarship, record 969, instead). The award covers the second-year tuition fee only, never living costs, and there is nothing to apply for before arrival - the application window is 1-15 April of the first year. No numeric grade threshold or scholarship-level IELTS figure is published (grades are ranked comparatively), so min_gpa/min_ielts are not recorded. Prospective students reading this record should pair it with record 325 (the pre-entry KTH Scholarship, which requires KTH as first priority at universityadmissions.se).$req$, 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-one-year-scholarship-1.290744', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-one-year-scholarship-1.290744', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-one-year-scholarship-1.290744', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 18) from KTH's official 'KTH One-Year Scholarship' page fetched the same day (covers the tuition fee for the second year of a two-year master's programme at KTH; awarded to current KTH master's students with outstanding first-year results; application window 1-15 April; selection on grades from first-year courses; in 2025, 5% of eligible applicants nominated - 12 of 220; eligibility = fee-paying student with satisfactory grades to progress to year two; not available for joint master programmes or EIT programmes; no living costs). The scheme was spotted in cleanup pass 111 while rewriting record 325 (the pre-entry KTH Scholarship) and is catalogued here as the separate named award it is. Award stored as NULL (SEK, 'year', 'variable'): a full second-year tuition waiver whose krona value follows the programme fee, which the fetched page does not price. deadline_date NULL/'not_published': the page publishes the recurring 1-15 April window rather than a single next-round date; status 'upcoming' ahead of the next April window. min_gpa/min_ielts NULL. university_id set to the existing KTH record (86), a university_scholarships row added, and a dedicated verified source inserted for the page.$note$, 86, NULL, 'SEK', 'year', 'variable', NULL, 'Full tuition fee of the SECOND year of a two-year KTH master’s programme, awarded after outstanding first-year results (5% nominated in 2025); living costs not included', 'The scholarship waives the KTH tuition fee in full for the second year of a two-year master’s programme (first-year fee unaffected); the fee amount itself varies by programme.', 'No scholarship-level IELTS figure; English requirements were met at programme admission.', $j$["Scholarship application on the KTH One-Year Scholarship page during the 1-15 April window of the first year", "First-year course grades at KTH (selection is based on the grades from courses completed in the first year)", "Fee-paying status with satisfactory grades to progress to the second year"]$j$, NULL, NULL, $json$[{"pattern": "Annual, for current first-year students at KTH only: application 1-15 April of the first year, selection on first-year course grades, award waives the second-year tuition fee (joint and EIT programmes excluded)"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (969, 'KTH Joint Programme Scholarship', 'KTH Royal Institute of Technology', 'Sweden', 'Full Tuition Waiver', 0, 'For fee-paying students attending one or two semesters at KTH from the autumn as part of one of the five listed joint programmes: the scholarship application runs each year 1-15 April (first-year-at-KTH applicants who did not apply via universityadmissions.se must also email degree/transcript scans to info@kth.se in that window; second-year-at-KTH applicants email first-year transcripts). The fetched page frames the round for KTH periods beginning in autumn 2026; no dated future round is published, so no deadline_date is recorded.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["Five named joint programmes with one or two semesters at KTH: Computer Simulations for Science and Engineering (COSSE); Decentralized Smart Energy Systems (DENSYS, Erasmus+ - only students without an Erasmus Mundus or DENSYS consortium scholarship); EIT Digital (first or third semester at KTH, no EIT consortium scholarship, registration-fee condition); Innovative Sustainable Energy Engineering (Nordic Five Tech); Transport Mobility and Innovation (EIT Urban Mobility)"]$j$, $j$["Fee-paying students in the listed joint programmes (fee-paying as defined by University Admissions in Sweden - broadly non-EU/EEA/Swiss citizens without an exempting permit); Erasmus Mundus Scholarship holders and students in unlisted EIT programmes are not eligible"]$j$, NULL, NULL, false, true, $desc$The KTH Joint Programme Scholarship covers the tuition fee for the study period spent at KTH for students participating in one of five named joint master's programmes: Computer Simulations for Science and Engineering (COSSE), Decentralized Smart Energy Systems (DENSYS - only students who do not hold an Erasmus Mundus Scholarship or a DENSYS consortium scholarship), EIT Digital (only students with their first or third semester at KTH who hold no whole or partial EIT Digital consortium scholarship, with the registration-fee condition for first-semester entrants), Innovative Sustainable Energy Engineering (Nordic Five Tech), and Transport Mobility and Innovation (EIT Urban Mobility). It does not include living costs, and it is highly selective - in 2025, 3% of the eligible scholarship applicants were nominated (2 of 62). Applicants must be fee-paying students (as defined by University Admissions) attending one or two semesters at KTH within their joint programme. Two neighbouring routes to keep straight: applicants to the Molecular Techniques in Life Science or Biostatistics and Data Science programmes are not eligible here and must apply for the KTH Scholarship instead (record 325), and applicants to the master's programme in Mathematics apply for a scholarship through Stockholm University; students in EIT programmes not on the list and Erasmus Mundus Scholarship holders cannot apply at all. Selection is primarily on academic excellence - grades (GPA or equivalent), the ranking of the bachelor's university, and (for students spending their second year at KTH) previous studies within the joint programme. The application window is 1-15 April each year, with grade scans emailed to info@kth.se by applicants who did not come through universityadmissions.se or who spend their second year at KTH.$desc$, $req$You must be a fee-paying student (University Admissions definition) who will attend one or two semesters at KTH as part of COSSE, DENSYS, EIT Digital, Innovative Sustainable Energy Engineering (Nordic Five Tech) or Transport Mobility and Innovation (EIT Urban Mobility) - with the consortium-scholarship exclusions above (no Erasmus Mundus or DENSYS/EIT Digital consortium scholarship holders) and the EIT Digital semester/registration-fee conditions. Apply online during 1-15 April; first-year-at-KTH applicants who did not apply through universityadmissions.se must also send scans of the original bachelor's degree and transcripts (with official translations if not in English) to info@kth.se during the same window, and second-year-at-KTH applicants send first-year joint-programme transcripts. The waiver covers only the KTH study period's tuition, never living costs or semesters at partner universities. Grades are assessed comparatively with no published numeric cutoff and there is no scholarship-level IELTS figure, so min_gpa/min_ielts are not recorded.$req$, 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-joint-programme-scholarship-1.611327', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-joint-programme-scholarship-1.611327', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-joint-programme-scholarship-1.611327', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 18) from KTH's official 'KTH Joint Programme Scholarship' page fetched the same day (covers the tuition fee for the study period spent at KTH, no living costs; in 2025, 3% of eligible applicants nominated - 2 of 62; eligibility = fee-paying students attending one or two semesters at KTH beginning in autumn 2026 within COSSE, DENSYS (no Erasmus Mundus/DENSYS consortium holders), EIT Digital (first or third semester at KTH, registration fee by 13 April for first-semester entrants, no EIT consortium scholarship), Innovative Sustainable Energy Engineering (Nordic Five Tech) or Transport Mobility and Innovation (EIT Urban Mobility); MTLS/Biostatistics applicants routed to the KTH Scholarship instead and Mathematics applicants to Stockholm University; unlisted EIT programmes and Erasmus Mundus holders ineligible; application 1-15 April with degree/transcript scans to info@kth.se for non-universityadmissions.se first-year entrants and first-year transcripts for second-year entrants; selection on grades, bachelor's-university ranking and previous joint-programme studies). The scheme was spotted in cleanup pass 111 while rewriting record 325 and is catalogued here as the separate named award it is. Award stored as NULL (SEK, 'year', 'variable'): a waiver of the KTH-period fee (one or two semesters) whose krona value follows the programme. deadline_date NULL/'not_published': the fetched page describes the round for KTH periods beginning in autumn 2026 and the recurring 1-15 April window rather than a dated future round; status 'upcoming' ahead of the next April window. min_gpa/min_ielts NULL. university_id set to the existing KTH record (86), a university_scholarships row added, and a dedicated verified source inserted for the page.$note$, 86, NULL, 'SEK', 'year', 'variable', NULL, 'Tuition fee for the study period spent at KTH (one or two semesters) in five named joint programmes: COSSE, DENSYS, EIT Digital, Innovative Sustainable Energy Engineering (Nordic Five Tech), Transport Mobility and Innovation (EIT Urban Mobility); 3% nominated in 2025', 'The waiver covers only the tuition fee of the one or two semesters spent at KTH; partner-university semesters and living costs are outside the award.', 'No scholarship-level IELTS figure; English requirements follow each joint programme''s admission rules.', $j$["Online scholarship application in the 1-15 April window", "First-year-at-KTH applicants who did not apply via universityadmissions.se: scans of the original bachelor's degree and transcripts (official translations if not in English) emailed to info@kth.se during 1-15 April", "Second-year-at-KTH applicants: scans of first-year joint-programme transcripts emailed to info@kth.se", "Fee-paying status within one of the five listed joint programmes, observing the Erasmus Mundus / consortium-scholarship exclusions"]$j$, NULL, NULL, $json$[{"round": "KTH periods beginning autumn 2026 (fetched page)", "application": "April 1-15", "status": "upcoming"}, {"pattern": "Annual: application 1-15 April for fee-paying students in the five listed joint programmes spending one or two semesters at KTH from the following autumn; selection primarily on academic excellence"}]$json$);

