INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at) VALUES
(697, 136, 967, 'Axel Adler Scholarship for Sustainability', 'available', 'Full Tuition Waiver', 'Full tuition fee waived for a sustainability-focused master''s programme (2-12 awardees); paid directly to the university', true, false, 'CV + letter of motivation (max 3,000 characters each) ranked by academic staff', 'For fee-paying students admitted to a sustainability-focused master''s programme chosen as FIRST choice (apply by 15 Jan 2027; fee + documents by 1 Feb 2027; invitation ~10 Feb 2027; results 12 Apr 2027). Applied for inside the same application as the main Axel Adler Scholarship if eligible for both. Bachelor''s programmes and the distance Education for Sustainable Development master''s are excluded. Keep it by completing at least 75% of each semester''s credits; cannot be combined with another tuition scholarship.', 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship', 'https://www.gu.se/en/study-in-gothenburg/apply/scholarships-for-fee-paying-students/axel-adler-scholarship', 'verified', now()),
(698, 86, 968, 'KTH One-Year Scholarship', 'available', 'Full Tuition Waiver', 'Second-year tuition fee of a two-year master''s waived in full after outstanding first-year results (5% nominated in 2025)', true, false, 'First-year course grades at KTH', 'For CURRENT fee-paying students of a two-year KTH master''s only - nothing to apply for before starting. Apply 1-15 April of the first year; selection on first-year course grades; satisfactory progression to year two required. Not available for joint master programmes or EIT programmes (see the KTH Joint Programme Scholarship). Living costs not included.', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-one-year-scholarship-1.290744', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-one-year-scholarship-1.290744', 'verified', now()),
(699, 86, 969, 'KTH Joint Programme Scholarship', 'available', 'Full Tuition Waiver', 'Tuition fee of the one or two semesters spent at KTH waived in five named joint programmes (3% nominated in 2025)', true, false, 'Academic excellence (grades, bachelor''s-university ranking, joint-programme performance)', 'For fee-paying students in COSSE, DENSYS (no Erasmus Mundus/consortium holders), EIT Digital (1st or 3rd semester at KTH, no EIT scholarship), Innovative Sustainable Energy Engineering (Nordic Five Tech) or Transport Mobility and Innovation (EIT Urban Mobility). Apply 1-15 April; grade scans to info@kth.se where applicable. MTLS/Biostatistics students use the KTH Scholarship instead; Mathematics via Stockholm University. Covers only the KTH semesters, never living costs.', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-joint-programme-scholarship-1.611327', 'https://www.kth.se/en/studies/master/admissions/scholarships/kth-joint-programme-scholarship-1.611327', 'verified', now());

